/*!
 * Crafted with ❤ by Salla
 */
/**
 * Builds a per-detail availability map from SKU-level data.
 *
 * Exported as a pure function so it can be unit-tested independently of the
 * Stencil component (the @State availabilityMap backing-store is not accessible
 * via page.rootInstance in the Stencil mock-doc test environment).
 *
 * Status values:
 *   'available'    – at least one in-stock SKU for this detail + current selections
 *   'out_of_stock' – all matching SKUs are out of stock
 *   'impossible'   – no SKU intersection exists for this combination
 *
 * skus_availability is always the authoritative source when present; is_out is
 * consulted only as a last resort when a detail has no SKU data at all.
 *
 * For unlimited products (no SKU data, or all SKUs false), all options default
 * to available unless explicitly marked as out of stock.
 *
 * @param isProductAvailable – whether product is available at the parent level
 *        (e.g., quantity > 0 or -1 for unlimited). If true and all SKUs are false,
 *        treat as available (data is incomplete or product is unlimited).
 */
export function computeAvailabilityMap(optionsData, selectedOptions, isProductAvailable = true) {
    const map = {};
    if (!optionsData?.length)
        return map;
    const variantGroups = optionsData.filter(opt => opt.details?.some(d => d.skus_availability && Object.keys(d.skus_availability).length > 0));
    const isSingleGroup = variantGroups.length <= 1;
    // Non-advance options carry no variant SKUs — never let them constrain the intersection.
    const nonAdvanceOptionIds = new Set(optionsData.filter(opt => opt.is_advance === false).map(opt => opt.id));
    // Unlimited product (no SKU data) — all options default to available unless explicitly marked.
    if (variantGroups.length === 0) {
        for (const optionGroup of optionsData) {
            for (const detail of optionGroup.details) {
                map[detail.id] = detail.is_out ? 'out_of_stock' : 'available';
            }
        }
        return map;
    }
    // The isProductAvailable fallback (promote all-false SKUs to 'available') is only safe
    // when the product carries NO in-stock SKU anywhere — that signals placeholder/incomplete
    // SKU data for an unlimited product. If ANY SKU in the product is in stock, the data is
    // real and all-false details are genuinely out of stock; promoting them would let shoppers
    // pick an unfulfillable variant of a partially-available limited product.
    const productHasAnyTrueSku = variantGroups.some(opt => opt.details?.some(d => d.skus_availability && Object.values(d.skus_availability).some(Boolean)));
    const allowUnlimitedFallback = isProductAvailable && !productHasAnyTrueSku;
    for (const optionGroup of variantGroups) {
        const otherSelected = selectedOptions.filter(s => s.option_id !== optionGroup.id);
        for (const detail of optionGroup.details) {
            const skusAvail = detail.skus_availability;
            // No skus_availability data — fall back to is_out as last resort only.
            if (!skusAvail || !Object.keys(skusAvail).length) {
                map[detail.id] = detail.is_out ? 'out_of_stock' : 'available';
                continue;
            }
            const detailSkus = Object.keys(skusAvail).map(Number);
            const hasAnyTrueSku = detailSkus.some(sku => skusAvail[sku]);
            // No cross-group context yet — evaluate this detail's own SKUs directly.
            if (isSingleGroup || otherSelected.length === 0) {
                // If product is available but all SKUs are false, treat as available
                // (data incomplete or product is unlimited with placeholder SKU data).
                if (!hasAnyTrueSku && allowUnlimitedFallback) {
                    map[detail.id] = 'available';
                }
                else {
                    map[detail.id] = hasAnyTrueSku ? 'available' : 'out_of_stock';
                }
                continue;
            }
            // Intersect this detail's SKUs with those of each other selected detail.
            let candidates = detailSkus;
            for (const other of otherSelected) {
                if (nonAdvanceOptionIds.has(other.option_id))
                    continue; // skip non-advance options
                const otherSkus = new Set(Object.keys(other.skus_availability || {}).map(Number));
                candidates = candidates.filter(sku => otherSkus.has(sku));
            }
            // Empty intersection normally means an unfulfillable combination. But when the
            // unlimited fallback applies (no true SKU anywhere — placeholder data), there are
            // no real stock constraints, so a non-overlapping SKU set is a data artifact, not
            // an impossible combination.
            if (!candidates.length) {
                map[detail.id] = allowUnlimitedFallback ? 'available' : 'impossible';
                continue;
            }
            const hasAvailableCandidate = candidates.some(sku => skusAvail[sku]);
            // If product available but no candidates match true SKUs, treat as available.
            if (!hasAvailableCandidate && allowUnlimitedFallback) {
                map[detail.id] = 'available';
            }
            else {
                map[detail.id] = hasAvailableCandidate ? 'available' : 'out_of_stock';
            }
        }
    }
    return map;
}
